values (
  'en-league-of-legends-trivia',
  'League of Legends Trivia Challenge',
  'Summoner''s Rift, Baron Nashor and Worlds finals in packed stadiums: the MOBA that defined modern esports. How well do you know it?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'gaming'),
  '[{"id":"q1","question":"Which studio created League of Legends?","options":[{"id":"a","text":"Valve","is_correct":false},{"id":"b","text":"Blizzard Entertainment","is_correct":false},{"id":"c","text":"Riot Games","is_correct":true},{"id":"d","text":"Epic Games","is_correct":false}],"explanation":"Riot Games developed it and still publishes it; it was the studio''s debut title."},{"id":"q2","question":"In which year was League of Legends officially released?","options":[{"id":"a","text":"2007","is_correct":false},{"id":"b","text":"2009","is_correct":true},{"id":"c","text":"2011","is_correct":false},{"id":"d","text":"2013","is_correct":false}],"explanation":"It launched on 27 October 2009, after an open beta earlier that year."},{"id":"q3","question":"What is the name of the game''s main 5v5 map?","options":[{"id":"a","text":"Howling Abyss","is_correct":false},{"id":"b","text":"Twisted Treeline","is_correct":false},{"id":"c","text":"Summoner''s Rift","is_correct":true},{"id":"d","text":"Crystal Scar","is_correct":false}],"explanation":"Summoner''s Rift hosts the classic 5v5; the Howling Abyss is the one-lane ARAM map."},{"id":"q4","question":"How do you win a match on Summoner''s Rift?","options":[{"id":"a","text":"Reaching 100 team kills first","is_correct":false},{"id":"b","text":"Capturing all three altars","is_correct":false},{"id":"c","text":"Surviving for 30 minutes","is_correct":false},{"id":"d","text":"Destroying the enemy Nexus","is_correct":true}],"explanation":"The Nexus sits inside each base, guarded by turrets; destroying it ends the game."},{"id":"q5","question":"Which neutral monster grants the ''Hand of Baron'' buff when slain?","options":[{"id":"a","text":"Rift Herald","is_correct":false},{"id":"b","text":"Elder Dragon","is_correct":false},{"id":"c","text":"Baron Nashor","is_correct":true},{"id":"d","text":"The Scuttle Crab","is_correct":false}],"explanation":"Slaying Baron Nashor buffs the whole team and empowers nearby minions for a siege."},{"id":"q6","question":"Which champion is known as the Nine-Tailed Fox?","options":[{"id":"a","text":"Akali","is_correct":false},{"id":"b","text":"Ahri","is_correct":true},{"id":"c","text":"Evelynn","is_correct":false},{"id":"d","text":"Katarina","is_correct":false}],"explanation":"Ahri, the mid-lane mage from Ionia, is the kitsune-inspired Nine-Tailed Fox."},{"id":"q7","question":"What is the highest rank on League''s ranked ladder?","options":[{"id":"a","text":"Diamond","is_correct":false},{"id":"b","text":"Master","is_correct":false},{"id":"c","text":"Grandmaster","is_correct":false},{"id":"d","text":"Challenger","is_correct":true}],"explanation":"Above Master and Grandmaster sits Challenger, reserved for the top players of each region."},{"id":"q8","question":"Which team won the first League of Legends World Championship in 2011?","options":[{"id":"a","text":"SK Telecom T1","is_correct":false},{"id":"b","text":"Fnatic","is_correct":true},{"id":"c","text":"Cloud9","is_correct":false},{"id":"d","text":"G2 Esports","is_correct":false}],"explanation":"Fnatic took the Season 1 title at DreamHack in Sweden; SKT didn''t lift the trophy until 2013."}]'::jsonb,
  null,
  array['league of legends', 'moba', 'esports', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
