ion":"Matar al Barón Nashor potencia a todo el equipo y a sus súbditos cercanos para asediar."},{"id":"q6","question":"¿Qué campeona es conocida como el Zorro de Nueve Colas?","options":[{"id":"a","text":"Akali","is_correct":false},{"id":"b","text":"Evelynn","is_correct":false},{"id":"c","text":"Ahri","is_correct":true},{"id":"d","text":"Katarina","is_correct":false}],"explanation":"Ahri, la maga de Jonia de la calle central, es la kitsune del juego."},{"id":"q7","question":"¿Cuál es el rango más alto de la escalera clasificatoria?","options":[{"id":"a","text":"Diamante","is_correct":false},{"id":"b","text":"Maestro","is_correct":false},{"id":"c","text":"Retador","is_correct":true},{"id":"d","text":"Gran Maestro","is_correct":false}],"explanation":"Por encima de Maestro y Gran Maestro está Retador, reservado a los mejores de cada región."},{"id":"q8","question":"¿Qué equipo ganó el primer Mundial de League of Legends, en 2011?","options":[{"id":"a","text":"SK Telecom T1","is_correct":false},{"id":"b","text":"Cloud9","is_correct":false},{"id":"c","text":"G2 Esports","is_correct":false},{"id":"d","text":"Fnatic","is_correct":true}],"explanation":"Fnatic se llevó el título de la primera temporada en DreamHack, Suecia; SKT no ganó hasta 2013."}]'::jsonb,
