insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-counter-strike-trivia',
  'Counter-Strike Trivia Challenge',
  'From a Half-Life mod to the most-watched tactical shooter on the planet: Dust2, the AWP and two decades of clutches. Locked in?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'gaming'),
  '[{"id":"q1","question":"Counter-Strike began life as a community mod for which game?","options":[{"id":"a","text":"Quake III Arena","is_correct":false},{"id":"b","text":"Half-Life","is_correct":true},{"id":"c","text":"Unreal Tournament","is_correct":false},{"id":"d","text":"Doom II","is_correct":false}],"explanation":"It shipped as a Half-Life mod in 1999 before Valve hired its creators and turned it into a franchise."},{"id":"q2","question":"Which version, released in 2012, defined the modern competitive era?","options":[{"id":"a","text":"Condition Zero","is_correct":false},{"id":"b","text":"Counter-Strike: Source","is_correct":false},{"id":"c","text":"Global Offensive","is_correct":true},{"id":"d","text":"Counter-Strike 1.6","is_correct":false}],"explanation":"CS:GO launched in August 2012 and reigned until Counter-Strike 2 replaced it."},{"id":"q3","question":"Which engine does Counter-Strike 2 run on?","options":[{"id":"a","text":"GoldSrc","is_correct":false},{"id":"b","text":"Source","is_correct":false},{"id":"c","text":"Source 2","is_correct":true},{"id":"d","text":"Unreal Engine 5","is_correct":false}],"explanation":"CS2 moved the series to Source 2 when it launched in 2023, with smoke that fills space volumetrically."},{"id":"q4","question":"What is the most iconic map in the series, set in a Middle Eastern desert?","options":[{"id":"a","text":"Aztec","is_correct":false},{"id":"b","text":"Train","is_correct":false},{"id":"c","text":"Cobblestone","is_correct":false},{"id":"d","text":"Dust II","is_correct":true}],"explanation":"Dust II has been the game''s calling card since 2001 — and the home of ''rush B''."},{"id":"q5","question":"In bomb defusal, what are the Terrorists trying to do?","options":[{"id":"a","text":"Rescue the hostages","is_correct":false},{"id":"b","text":"Plant the C4 at a bomb site","is_correct":true},{"id":"c","text":"Capture the enemy flag","is_correct":false},{"id":"d","text":"Escort the bomb carrier to the exit","is_correct":false}],"explanation":"Terrorists plant the bomb at site A or B; Counter-Terrorists must defuse it in time."},{"id":"q6","question":"How many bomb sites does a classic defusal map have?","options":[{"id":"a","text":"One","is_correct":false},{"id":"b","text":"Two","is_correct":true},{"id":"c","text":"Three","is_correct":false},{"id":"d","text":"Four","is_correct":false}],"explanation":"Two — A and B — which is why mid control decides so many rounds."},{"id":"q7","question":"Which sniper rifle is famous for killing with a single shot to the body?","options":[{"id":"a","text":"The Scout (SSG 08)","is_correct":false},{"id":"b","text":"The AWP","is_correct":true},{"id":"c","text":"The G3SG1","is_correct":false},{"id":"d","text":"The AUG","is_correct":false}],"explanation":"The AWP costs a fortune and earns it: one hit to the torso ends the round for its target."},{"id":"q8","question":"Which team won the first CS:GO Major, DreamHack Winter 2013?","options":[{"id":"a","text":"Ninjas in Pyjamas","is_correct":false},{"id":"b","text":"Virtus.pro","is_correct":false},{"id":"c","text":"Astralis","is_correct":false},{"id":"d","text":"Fnatic","is_correct":true}],"explanation":"Fnatic beat Ninjas in Pyjamas in Jönköping; Astralis''s Major dynasty came years later."}]'::jsonb,
  null,
  array['counter-strike', 'fps', 'esports', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
