insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-among-us-trivia',
  'Among Us Trivia Challenge',
  'Tasks, vents and emergency meetings: the little space game that took over the internet. Don''t act sus — you might be the Impostor.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'gaming'),
  '[{"id":"q1","question":"Which studio made Among Us?","options":[{"id":"a","text":"Devolver Digital","is_correct":false},{"id":"b","text":"InnerSloth","is_correct":true},{"id":"c","text":"Mojang","is_correct":false},{"id":"d","text":"Supercell","is_correct":false}],"explanation":"InnerSloth, a small indie team, released it in 2018 — two years before it exploded."},{"id":"q2","question":"In which year was Among Us first released?","options":[{"id":"a","text":"2016","is_correct":false},{"id":"b","text":"2018","is_correct":true},{"id":"c","text":"2020","is_correct":false},{"id":"d","text":"2022","is_correct":false}],"explanation":"It came out in June 2018 to little attention; the boom came later."},{"id":"q3","question":"In which year did it become a global phenomenon, driven by streamers?","options":[{"id":"a","text":"2018","is_correct":false},{"id":"b","text":"2019","is_correct":false},{"id":"c","text":"2020","is_correct":true},{"id":"d","text":"2022","is_correct":false}],"explanation":"Twitch and YouTube turned it into the pandemic''s favourite party game in mid-2020."},{"id":"q4","question":"What was the game''s original map?","options":[{"id":"a","text":"Mira HQ","is_correct":false},{"id":"b","text":"The Skeld","is_correct":true},{"id":"c","text":"Polus","is_correct":false},{"id":"d","text":"The Airship","is_correct":false}],"explanation":"The Skeld, the spaceship, came first; the other maps were added later."},{"id":"q5","question":"What do Impostors use to move quickly between rooms?","options":[{"id":"a","text":"Teleporters","is_correct":false},{"id":"b","text":"Elevators","is_correct":false},{"id":"c","text":"Vents","is_correct":true},{"id":"d","text":"Escape pods","is_correct":false}],"explanation":"Impostors — and the Engineer role — can travel the vent network; a classic tell."},{"id":"q6","question":"Besides ejecting every Impostor, how can Crewmates win?","options":[{"id":"a","text":"Surviving for 10 minutes","is_correct":false},{"id":"b","text":"Finishing all their tasks","is_correct":true},{"id":"c","text":"Finding every vent","is_correct":false},{"id":"d","text":"Repairing the ship''s engines","is_correct":false}],"explanation":"Fill the taskbar and the crew wins even with Impostors still aboard."},{"id":"q7","question":"Which huge map, added in 2021, is set on a flying ship?","options":[{"id":"a","text":"The Fungle","is_correct":false},{"id":"b","text":"Mira HQ","is_correct":false},{"id":"c","text":"The Dropship","is_correct":false},{"id":"d","text":"The Airship","is_correct":true}],"explanation":"The Airship, based on the Henry Stickmin series, was the biggest map in the game when it arrived."},{"id":"q8","question":"Which of these is NOT a real Among Us map?","options":[{"id":"a","text":"The Skeld","is_correct":false},{"id":"b","text":"Polus","is_correct":false},{"id":"c","text":"The Citadel","is_correct":true},{"id":"d","text":"The Fungle","is_correct":false}],"explanation":"The Citadel is invented; the real maps are The Skeld, Mira HQ, Polus, The Airship and The Fungle."}]'::jsonb,
  null,
  array['among us', 'multiplayer', 'party-game', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

